  void LayoutStudio(){if(IsDisposed)return;float scale=DeviceDpi/96f;int width=Math.Max(180,ClientSize.Width-(int)(24*scale));foreach(Control c in root.Controls)c.Width=width;bool narrow=width<850*scale;columns.SuspendLayout();columns.Controls.Clear();columns.ColumnStyles.Clear();columns.RowStyles.Clear();columns.ColumnCount=narrow?1:rgb?3:2;columns.RowCount=narrow?3:rgb?1:2;columns.Height=(int)((narrow?rgb?1400:1100:rgb?650:650)*scale);if(narrow){columns.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));columns.RowStyles.Add(new RowStyle(SizeType.Absolute,220*scale));columns.RowStyles.Add(new RowStyle(SizeType.Absolute,(rgb?740:370)*scale));columns.RowStyles.Add(new RowStyle(SizeType.Percent,100));columns.Controls.Add(deviceCard,0,0);columns.Controls.Add(controlCard,0,1);columns.Controls.Add(previewCard,0,2);}else if(rgb){columns.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,28));columns.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,38));columns.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,34));columns.RowStyles.Add(new RowStyle(SizeType.Percent,100));columns.Controls.Add(deviceCard,0,0);columns.Controls.Add(controlCard,1,0);columns.Controls.Add(previewCard,2,0);}else{columns.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,42));columns.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,58));columns.RowStyles.Add(new RowStyle(SizeType.Absolute,200*scale));columns.RowStyles.Add(new RowStyle(SizeType.Percent,100));columns.Controls.Add(deviceCard,0,0);columns.SetColumnSpan(deviceCard,2);columns.Controls.Add(controlCard,0,1);columns.Controls.Add(previewCard,1,1);identity.Height=(int)(50*scale);}columns.ResumeLayout();}
  async Task ReloadProfiles(){try{string[] files=await Task.Run(()=>Directory.Exists(StudioProfiles.Root)?Directory.GetFiles(StudioProfiles.Root,(rgb?"RGB":"Display")+"-*.json"):new string[0]);if(IsDisposed)return;profileList.Items.Clear();profileList.Items.AddRange(files);if(files.Length>0)profileList.SelectedIndex=0;}catch(Exception e){ShowError(e);}}
  async Task LoadIcc(){try{var reply=await workspace.Display.Execute(new StudioCommand{Action="profiles"},lifetime.Token);CheckReply(reply);if(IsDisposed)return;icc.Items.Clear();icc.Items.Add("Keep current profile");icc.Items.AddRange(reply.Profiles);icc.SelectedIndex=0;}catch(Exception ex){ShowError(ex);}}
  static void CheckReply(StudioReply reply){if(reply==null)throw new IOException("No provider response");if(!string.IsNullOrEmpty(reply.Error))throw new IOException(reply.Error);}
  async Task Run(Func<Task> action){if(busy||IsDisposed)return;busy=true;SetEnabled();try{await action();}catch(OperationCanceledException){}catch(Exception ex){ShowError(ex);}finally{busy=false;if(!IsDisposed)SetEnabled();}}
  void ShowError(Exception e){if(!IsDisposed)message.Text="Unavailable / operation failed: "+e.Message;}
  async Task Discover(){await Run(async()=>{devices.Items.Clear();Selected();message.Text="Discovering in background...";if(Provider==null)throw new IOException("Configure and connect a local OpenRGB server first");var reply=await Provider.Execute(new StudioCommand(),lifetime.Token);CheckReply(reply);if(IsDisposed)return;devices.Items.Clear();devices.Items.AddRange(reply.Devices.ToArray());if(devices.Items.Count>0)devices.SelectedIndex=0;if(compactControls)SyncCompactDisplays();message.Text=reply.Message+(rgb?"\r\nUse an existing OpenRGB server bound to loopback. Pause vendor RGB utilities and Windows Dynamic Lighting before applying lighting changes.":(reply.Devices.Any(d=>d.Brightness.HasValue)?"\r\nBrightness changes immediately as you drag. Other settings use Apply other settings.":"\r\nEnable DDC/CI in the monitor OSD, then Refresh. Unsupported controls stay disabled."));});}
  StudioDevice Device{get{return devices.SelectedItem as StudioDevice;}}
  void Selected(){if(loading)return;loading=true;try{var d=Device;mode.Items.Clear();zone.Items.Clear();temperature.Items.Clear();if(d!=null){hdr.Checked=d.HdrEnabled==true;hdr.Text="Enable HDR - "+d.HdrStatus;identity.Text=d.Name+"\r\n"+d.Detail+"\r\n"+d.Status;brightness.Value=d.Brightness??0;contrast.Value=d.Contrast??0;mode.Items.AddRange(d.Modes.ToArray());if(d.Modes.Count>0)mode.SelectedIndex=Math.Max(0,Math.Min(d.Modes.Count-1,d.ActiveMode));zone.Items.Add("All zones");zone.Items.AddRange(d.Zones.ToArray());zone.SelectedIndex=0;for(int i=1;i<=8;i++)if((d.TemperatureFlags&(1u<<(i-1)))!=0)temperature.Items.Add(new TemperatureChoice(i));if(d.Temperature.HasValue)for(int i=0;i<temperature.Items.Count;i++)if(((TemperatureChoice)temperature.Items[i]).Value==d.Temperature.Value)temperature.SelectedIndex=i;if(temperature.Items.Count==0){temperature.Items.Add("Temperature unavailable");temperature.SelectedIndex=0;}iccInfo.Text="Current profile:\r\n"+(d.Profile==null?"Unavailable":Path.GetFileName(d.Profile));}else{identity.Text="No connected devices";hdr.Checked=false;hdr.Text="Enable HDR - unavailable";}}finally{loading=false;}ModeChanged();SetEnabled();}
  sealed class TemperatureChoice{public int Value;public TemperatureChoice(int v){Value=v;}public override string ToString(){return new[]{"","4000 K","5000 K","6500 K (D65)","7500 K","8200 K","9300 K","10000 K","11500 K"}[Value];}}
  void ModeChanged(){var m=mode.SelectedItem as StudioMode;if(rgb&&m!=null){brightness.Value=OpenRgbStudio.HasRange(m.Brightness,m.BrightnessMin,m.BrightnessMax)?OpenRgbStudio.Normalize(m.Brightness,m.BrightnessMin,m.BrightnessMax):0;speed.Value=OpenRgbStudio.HasRange(m.Speed,m.SpeedMin,m.SpeedMax)?OpenRgbStudio.Normalize(m.Speed,m.SpeedMin,m.SpeedMax):0;}SetEnabled();}
  void SetEnabled(){var d=Device;bool available=!busy&&d!=null&&!d.Ambiguous;var m=mode.SelectedItem as StudioMode;hdr.Enabled=available&&!rgb&&!liveWriting&&d.HdrCanToggle&&d.HdrEnabled.HasValue;brightness.Enabled=available&&(rgb?m!=null&&(m.Flags&16)!=0&&OpenRgbStudio.HasRange(m.Brightness,m.BrightnessMin,m.BrightnessMax):d.Brightness.HasValue);contrast.Enabled=available&&!rgb&&d.Contrast.HasValue;temperature.Enabled=available&&!rgb&&d.Temperature.HasValue&&temperature.Items.OfType<TemperatureChoice>().Any();speed.Enabled=available&&rgb&&m!=null&&(m.Flags&1)!=0&&OpenRgbStudio.HasRange(m.Speed,m.SpeedMin,m.SpeedMax);wheel.Enabled=hex.Enabled=red.Enabled=green.Enabled=blue.Enabled=available&&rgb&&m!=null&&(m.Flags&96)!=0;mode.Enabled=available;zone.Enabled=available&&m!=null&&(m.Flags&32)!=0;apply.Enabled=available&&!liveWriting;restore.Enabled=!busy&&!liveWriting&&Previous.Count>0;refresh.Enabled=!busy&&!liveWriting;devices.Enabled=!busy&&!liveWriting;save.Enabled=available;import.Enabled=!busy;load.Enabled=!busy;}
  void SetColour(Color c){loading=true;try{hex.Text=ColorTranslator.ToHtml(Color.FromArgb(c.R,c.G,c.B));red.Value=c.R;green.Value=c.G;blue.Value=c.B;preview.Colour=c;preview.Invalidate();}finally{loading=false;}}
  void UpdateHex(){try{if(!System.Text.RegularExpressions.Regex.IsMatch(hex.Text,"^#[a-fA-F0-9]{6}$"))throw new FormatException("Use a six-digit HEX colour, for example #FF1744");SetColour(ColorTranslator.FromHtml(hex.Text));}catch(Exception e){ShowError(e);}}
  List<StudioCommand> Intended(){var d=Device;if(d==null)throw new InvalidOperationException("Select a device");var targets=linked.Checked?devices.Items.Cast<StudioDevice>().Where(x=>!x.Ambiguous).ToArray():devices.SelectedItems.Cast<StudioDevice>().Where(x=>!x.Ambiguous).ToArray();return targets.Select(x=>new StudioCommand{Action="apply",Id=x.Id,Mode=rgb&&mode.SelectedItem!=null?((StudioMode)mode.SelectedItem).Name:null,Zone=rgb&&zone.SelectedItem is StudioZone?((StudioZone)zone.SelectedItem).Id:null,Hex=rgb&&hex.Enabled?hex.Text:null,Brightness=brightness.Enabled?linked.Checked&&!rgb&&!x.Brightness.HasValue?(int?)null:brightness.Value:(int?)null,Contrast=!rgb&&contrast.Enabled&&!linked.Checked?contrast.Value:(int?)null,Temperature=!rgb&&temperature.Enabled&&!linked.Checked&&temperature.SelectedItem!=null?((TemperatureChoice)temperature.SelectedItem).Value:(int?)null,Speed=rgb&&speed.Enabled?speed.Value:(int?)null,Profile=!rgb&&icc.SelectedIndex>0?icc.SelectedItem as string:null}).ToList();}
  StudioProfile MakeProfile(string name){return new StudioProfile{Name=name,Kind=rgb?"RGB":"Display",Utc=DateTime.UtcNow,Observations=devices.Items.Cast<StudioDevice>().Select(x=>StudioJson.Clone(x)).ToList(),Targets=Intended()};}
  async Task SavePreset(){try{using(var dialog=new SaveFileDialog{Filter="Studio JSON|*.json",InitialDirectory=Directory.Exists(StudioProfiles.Root)?StudioProfiles.Root:ReportStore.Root,FileName=(rgb?"RGB":"Display")+"-Custom.json"})if(dialog.ShowDialog()==DialogResult.OK){var p=MakeProfile(Path.GetFileNameWithoutExtension(dialog.FileName));string file=dialog.FileName;await Task.Run(()=>StudioProfiles.Save(p,file));if(!IsDisposed){message.Text="Preset saved. Loading always requires explicit Apply.";await ReloadProfiles();}}}catch(Exception ex){ShowError(ex);}}
  async Task Apply(bool rollback,StudioProfile profile){brightnessDebounce.Stop();pendingBrightness.Clear();if(rgb&&(!conflicts.Checked||benchmarking()&&!overrideBench.Checked)){message.Text="Pause competing RGB controllers; RGB writes are blocked during benchmarks unless explicitly enabled.";return;}List<StudioCommand> targets;try{targets=rollback?Previous.Values.Select(x=>new StudioCommand{Action="restore",Id=x.Id,Snapshot=x}).ToList():profile!=null?profile.Targets:Intended();if(targets.Any(x=>x.Profile!=null||x.Snapshot!=null&&x.Snapshot.RestoreIcc)&&!sdr.Checked&&!rgb){message.Text="Confirm SDR mode before associating ICC profiles. HDR profiles are unsupported.";return;}var validation=new StudioProfile{Name="Apply",Kind=rgb?"RGB":"Display",Targets=targets.Where(x=>x.Action=="apply").ToList()};if(!rollback)StudioProfiles.Validate(validation);if(targets.Count==0)throw new InvalidOperationException("No capable targets");string text=string.Join("\r\n",targets.Select(c=>{var d=devices.Items.Cast<StudioDevice>().FirstOrDefault(x=>x.Id==c.Id);return (d==null?"Missing device "+c.Id:d.Name)+": "+(rollback?"restore captured previous settings":StudioJson.Serialize(c));}).ToArray());if(MessageBox.Show(this,text+"\r\n\r\nChanges are best effort. A failure may leave earlier settings changed. Continue?",rollback?"Restore previous":"Review exact changes",MessageBoxButtons.OKCancel,MessageBoxIcon.Information)!=DialogResult.OK)return;}catch(Exception ex){ShowError(ex);return;}
   await Run(async()=>{Directory.CreateDirectory(StudioProfiles.Root);using(var ownership=new FileStream(Path.Combine(StudioProfiles.Root,"hardware-control.lock"),FileMode.OpenOrCreate,FileAccess.ReadWrite,FileShare.None)){var outcomes=new List<string>();foreach(var c in targets){lifetime.Token.ThrowIfCancellationRequested();var d=devices.Items.Cast<StudioDevice>().SingleOrDefault(x=>x.Id==c.Id&&!x.Ambiguous);if(d==null){outcomes.Add("Missing/ambiguous device: skipped "+c.Id);continue;}try{if(!rollback){var read=await Provider.Execute(new StudioCommand{Action="read",Id=c.Id},lifetime.Token);CheckReply(read);var snapshot=StudioJson.Clone(read.Devices.Single(x=>x.Id==c.Id));StudioDevice earlier;if(Previous.TryGetValue(c.Id,out earlier)){snapshot.Brightness=earlier.Brightness??snapshot.Brightness;snapshot.Contrast=earlier.Contrast??snapshot.Contrast;snapshot.Temperature=earlier.Temperature??snapshot.Temperature;if(earlier.RestoreIcc){snapshot.Profile=earlier.Profile;snapshot.PerUserProfiles=earlier.PerUserProfiles;}}snapshot.RestoreIcc=c.Profile!=null||earlier!=null&&earlier.RestoreIcc;if(!snapshot.RestoreIcc)snapshot.Profile=null;Previous[c.Id]=snapshot;}var reply=await Provider.Execute(c,lifetime.Token);CheckReply(reply);outcomes.Add(d.Name+": "+reply.Message);if(rollback)Previous.Remove(c.Id);}catch(Exception ex){outcomes.Add(d.Name+": FAILED / settings may be partially changed: "+ex.Message);}if(IsDisposed)return;message.Text=string.Join("\r\n",outcomes.ToArray());}message.Text=string.Join("\r\n",outcomes.ToArray())+"\r\nRestore previous remains available for captured devices.";}});
  }
  void DrawDevice(object sender,DrawItemEventArgs e){if(e.Index<0)return;var d=(StudioDevice)devices.Items[e.Index];bool selected=(e.State&DrawItemState.Selected)!=0;using(var b=new SolidBrush(selected?Theme.SelectedSurface:Theme.Surface))e.Graphics.FillRectangle(b,e.Bounds);using(var p=new Pen(selected?Theme.Accent:Theme.Line))e.Graphics.DrawRectangle(p,e.Bounds.X+2,e.Bounds.Y+2,e.Bounds.Width-5,e.Bounds.Height-5);TextRenderer.DrawText(e.Graphics,d.Name,Font,new Rectangle(e.Bounds.X+12,e.Bounds.Y+7,e.Bounds.Width-24,22),Theme.Text,TextFormatFlags.EndEllipsis);using(var f=Theme.Face(9))TextRenderer.DrawText(e.Graphics,d.Status+" / "+d.Detail,f,new Rectangle(e.Bounds.X+12,e.Bounds.Y+30,e.Bounds.Width-24,20),Theme.Muted,TextFormatFlags.EndEllipsis);}
  public void InvalidateDevices(){if(IsDisposed)return;if(hdrWriting){brightnessDebounce.Stop();pendingBrightness.Clear();return;}brightnessDebounce.Stop();pendingBrightness.Clear();lifetime.Cancel();lifetime=new CancellationTokenSource();devices.Items.Clear();Selected();message.Text="Display/device topology or power state changed. Refresh to read capabilities again. Hardware changes have been disabled.";}
  protected override void Dispose(bool disposing){if(disposing){if(compactControls)devices.Dispose();brightnessDebounce.Dispose();pendingBrightness.Clear();lifetime.Cancel();}base.Dispose(disposing);}
